const discoveries = ['j_blueprint', 'e_negative', 'e_foil', 'e_holo', 'e_polychrome'];
const allTagIds = fixtures.find(row => row.ante === 2 && row.mode === 'all').pool;

test('24-slot tag pools match native original discovery/ante gates and fully banned fallback', () => {
  for (const row of fixtures) {
    const context = contextFor(row);
    assert.deepEqual(getApkTagPool(context), row.pool, `${row.seed}:${row.ante}:${row.mode}`);
  }
});

function contextFor(row) {
  return {
    ante: row.ante,
    discoveredCentreIds: row.mode === 'all' ? discoveries : row.mode === 'partial' ? discoveries.filter((_,i) => i % 2 === 0) : [],
    bannedKeys: row.mode === 'banned' ? allTagIds : [],
    visibleHandOrder: row.hands,
  };
}

test('144 original native tag/orbital traces match exact streams and subsequent unkeyed RNG', () => {
  for (const row of fixtures) {
    const context = contextFor(row);
    let rng = createApkRng(row.seed);
    for (const [tagId, afterTag, hand, afterOrbital, streams] of row.draws) {
      const tag = chooseApkTag(rng, context);
      assert.equal(tag.tagId, tagId, `${row.seed}:${row.ante}:${row.mode}`);
      const tagNext = nextApkRandom(tag.rng);
      assert.equal(tagNext.value, afterTag);
      const orbital = chooseApkOrbitalHand(tagNext.rng, context);
      assert.equal(orbital.hand, hand);
      assert.deepEqual(orbital.rng.streams, streams);
      const orbitalNext = nextApkRandom(orbital.rng);
      assert.equal(orbitalNext.value, afterOrbital);
      rng = orbitalNext.rng;
    }
  }
});

test('orbital choice depends on saved visible order and JSON resume preserves the subsequent selection', () => {
  const row = fixtures[0]; const context = contextFor(row);
  const rng = createApkRng(row.seed);
  const first = chooseApkOrbitalHand(rng, context);
  const shifted = { ...context, visibleHandOrder: [...context.visibleHandOrder.slice(1), context.visibleHandOrder[0]] };
  const other = chooseApkOrbitalHand(rng, shifted);
  assert.notEqual(other.hand, first.hand);
  assert.deepEqual(other.rng, first.rng);
  const snapshot = JSON.parse(JSON.stringify({context, rng: first.rng, selectedHand: first.hand}));
  assert.equal(snapshot.selectedHand, first.hand);
  assert.deepEqual(chooseApkOrbitalHand(snapshot.rng, snapshot.context), chooseApkOrbitalHand(first.rng, context));
});
